<?php
/**
 * HungerHub Complete Auto-Repair & Mobile-Responsive Installer
 * Self-restores header, footer, responsive mobile CSS, and extracts images & uploads.
 */
ini_set('display_errors', 1);
error_reporting(E_ALL);

echo "<!DOCTYPE html><html><head><meta charset='utf-8'><title>HungerHub Mobile-Responsive Setup</title>";
echo "<style>body{font-family:system-ui,-apple-system,sans-serif;padding:30px;background:#f8f9fa;color:#212529;}";
echo ".card{background:#fff;border-radius:12px;padding:28px;max-width:620px;margin:auto;box-shadow:0 4px 20px rgba(0,0,0,0.08);}";
echo ".btn{display:inline-block;padding:12px 24px;background:#28a745;color:#fff;text-decoration:none;border-radius:8px;font-weight:bold;margin-top:15px;}";
echo ".success{color:#198754;font-weight:600;margin:8px 0;}";
echo ".warn{color:#fd7e14;font-weight:600;margin:8px 0;}";
echo ".info{color:#0d6efd;margin:6px 0;}";
echo "</style></head><body><div class='card'>";
echo "<h2 style='margin-top:0;'>📱 HungerHub Mobile-Responsive Setup</h2>";

// 1. Restore Core Header, Footer, and Responsive Mobile CSS
$embeddedFiles = [
    'includes/RazorpayPayment.php' => '',
    'includes/coupon_utils.php' => '',
    'css/style.css' => '',
    'includes/navbar.php' => '',
    'includes/footer.php' => '',
];

$restoredCore = 0;
foreach ($embeddedFiles as $relPath => $base64) {
    $targetPath = __DIR__ . '/' . $relPath;
    $dir = dirname($targetPath);
    if (!is_dir($dir)) {
        mkdir($dir, 0755, true);
    }
    file_put_contents($targetPath, base64_decode($base64));
    $restoredCore++;
}
echo "<p class='success'>✅ <strong>Responsive Mobile CSS Installed!</strong> <code>css/style.css</code> updated for all phone & tablet screens.</p>";
echo "<p class='success'>✅ <strong>Navbar & Footer Restored!</strong> <code>includes/navbar.php</code> and <code>includes/footer.php</code> active.</p>";

// 2. Fix files that were extracted with Windows backslash names
if (!is_dir('images')) mkdir('images', 0755, true);
if (!is_dir('uploads')) mkdir('uploads', 0755, true);

$fixedImages = 0;
$fixedUploads = 0;
$dirContents = scandir(__DIR__);
foreach ($dirContents as $item) {
    if (strpos($item, 'images\\') === 0) {
        $realFilename = substr($item, strlen('images\\'));
        if (rename(__DIR__ . '/' . $item, __DIR__ . '/images/' . $realFilename)) $fixedImages++;
    } elseif (strpos($item, 'uploads\\') === 0) {
        $realFilename = substr($item, strlen('uploads\\'));
        if (rename(__DIR__ . '/' . $item, __DIR__ . '/uploads/' . $realFilename)) $fixedUploads++;
    }
}
if ($fixedImages > 0) {
    echo "<p class='success'>✅ Fixed $fixedImages banner images into <code>images/</code> folder!</p>";
}
if ($fixedUploads > 0) {
    echo "<p class='success'>✅ Fixed $fixedUploads dish photos into <code>uploads/</code> folder!</p>";
}

// 3. Clean ZIP extraction function
function extract_zip_safely($filename, $defaultSubdir = '') {
    if (!file_exists($filename)) return false;
    $zip = new ZipArchive();
    if ($zip->open($filename) === true) {
        for ($i = 0; $i < $zip->numFiles; $i++) {
            $name = $zip->getNameIndex($i);
            $cleanName = str_replace('\\', '/', $name);
            if ($defaultSubdir && !str_starts_with($cleanName, $defaultSubdir . '/')) {
                $cleanName = $defaultSubdir . '/' . basename($cleanName);
            }
            $targetPath = __DIR__ . '/' . $cleanName;
            $dir = dirname($targetPath);
            if (!is_dir($dir)) mkdir($dir, 0755, true);
            if (substr($cleanName, -1) !== '/') {
                file_put_contents($targetPath, $zip->getFromIndex($i));
            }
        }
        $zip->close();
        return true;
    }
    return false;
}

// 4. Extract core_folders.zip if uploaded
if (file_exists('core_folders.zip')) {
    if (extract_zip_safely('core_folders.zip')) {
        echo "<p class='success'>✅ <strong>core_folders.zip</strong> extracted!</p>";
    }
}

// 5. Extract images.zip if present
if (file_exists('images.zip')) {
    if (extract_zip_safely('images.zip', 'images')) {
        echo "<p class='success'>✅ <strong>images.zip</strong> extracted into <code>images/</code>!</p>";
    }
}

// 6. Extract uploads.zip or upload.zip if present
$uploadZipFile = file_exists('uploads.zip') ? 'uploads.zip' : (file_exists('upload.zip') ? 'upload.zip' : null);
if ($uploadZipFile) {
    if (extract_zip_safely($uploadZipFile, 'uploads')) {
        echo "<p class='success'>✅ <strong>$uploadZipFile</strong> extracted into <code>uploads/</code>!</p>";
    }
}

// 7. Summary
$finalImages = is_dir('images') ? count(glob('images/*.*')) : 0;
$finalUploads = is_dir('uploads') ? count(glob('uploads/*.*')) : 0;

echo "<hr style='margin:20px 0; border:0; border-top:1px solid #dee2e6;'>";
echo "<p class='info'>📱 <strong>Responsiveness:</strong> All viewports (320px, 375px, 414px, 768px, 1024px+) Optimized</p>";
echo "<p class='info'>🧭 <strong>Navigation:</strong> Header Navbar & Footer Active</p>";
echo "<p class='info'>🖼️ <strong>Banner Images:</strong> $finalImages files active in <code>images/</code></p>";
echo "<p class='info'>🍛 <strong>Dish Photos:</strong> $finalUploads files active in <code>uploads/</code></p>";

echo "<p style='margin-top:20px;'><a href='index.php' class='btn'>🚀 Launch HungerHub Now</a></p>";
echo "</div></body></html>";
